def unfold(ics_text):
    # in .ics files a long line continues on the next line, which starts with a space
    lines = []
    for raw in ics_text.replace("\r\n", "\n").split("\n"):
        if raw.startswith(" ") and lines:
            lines[-1] = lines[-1] + raw[1:]
        else:
            lines.append(raw)
    return lines


def clean(value):
    # .ics escapes commas, semicolons and line breaks with a backslash
    return value.replace("\\n", " ").replace("\\,", ",").replace("\\;", ";").strip()


COURSE_NAMES = {
    "IDSI51002": "Data Storage",
    "IDSI51003": "Research Topics",
    "IDSI51004": "E-Business",
    "IDSI51005": "Business Data Science",
    "IDSI51006": "Computer Vision",
    "IDSI51007": "Machine Learning",
    "IDSI51008": "Knowledge Graphs",
    "ECOI51010": "Environmental Economics",
    "MGTM51010": "Leading Teams",
    "ISDS51041": "No-Code",
}


def is_this_term(category):
    # course codes end like "(202600-1951)", the career module is "AIDAMS3 - Career 26-27"
    return "(2026" in category or "26-27" in category


def course_name(category):
    # Moodle only gives the code: "IDSI51006 (202600-1951)" -> "Computer Vision"
    if "Career" in category:
        return "Career"
    code = category.split(" (")[0].split(" ")[-1]
    return COURSE_NAMES.get(code, code)


def short_title(summary):
    # Moodle adds "is due" or "closes" after the activity name
    for ending in [" is due", " due", " closes"]:
        if summary.lower().endswith(ending):
            summary = summary[:-len(ending)]
            break
    # some teachers repeat the date in the name: "Exercise 3 (Due on October 19, 10:00AM)"
    return summary.split(" (Due")[0].strip()


def to_timestamp(key, value):
    # "20261028T190000Z" -> "2026-10-28 19:00:00 UTC", a format Postgres understands
    date = f"{value[0:4]}-{value[4:6]}-{value[6:8]}"
    if len(value) == 8:
        return f"{date} 23:59:00 Europe/Paris"   # all-day event, no time given
    time = f"{value[9:11]}:{value[11:13]}:00"
    if value.endswith("Z"):
        return f"{date} {time} UTC"
    if "TZID=" in key:
        return f"{date} {time} {key.split('TZID=')[1]}"
    return f"{date} {time} Europe/Paris"


# 1. read every event in the calendar file
events = []
current = None
for line in unfold(_items[0]["json"].get("data") or ""):
    if line == "BEGIN:VEVENT":
        current = {}
    elif line == "END:VEVENT" and current is not None:
        events.append(current)
        current = None
    elif current is not None and ":" in line:
        key, value = line.split(":", 1)
        name = key.split(";")[0]          # "DTSTART;TZID=Europe/Paris" -> "DTSTART"
        current[name] = value
        if name == "DTSTART":
            current["DTSTART_KEY"] = key

# 2. keep this term's deadlines only
results = []
for event in events:
    category = clean(event.get("CATEGORIES", ""))
    summary = clean(event.get("SUMMARY", ""))

    if not is_this_term(category) or "DTSTART" not in event:
        continue
    if summary.lower().endswith(" opens"):
        continue

    results.append({
        "json": {
            "uid": event.get("UID", "").strip(),
            "chatId": OWNER_CHAT_ID,
            "course": course_name(category),
            "title": short_title(summary),
            "due": to_timestamp(event["DTSTART_KEY"], event["DTSTART"].strip()),
        }
    })

return results

